export function findBossPin(q: string) {
  const n = q.toLowerCase().trim()
  // An exact name first, so 'tree sentinel' is not answered by the Tree Sentinel duo.
  return bossPins.find((b) => b.name.toLowerCase() === n) ??
    bossPins.find((b) => n.includes(b.name.toLowerCase()) || b.name.toLowerCase().includes(n))
}
